import manifest from "./star-fields.json";

/**
 * Catalogue star fields around deep-sky targets, with credits.
 * Generated by scripts/fetch-star-fields.mjs; do not edit the JSON by hand.
 */
export const STAR_CREDIT = manifest.credit;
export const STAR_LICENSE = manifest.license;
export const STAR_LICENSE_URL = manifest.licenseUrl;

export function starFieldSrc(targetId: string): string | undefined {
  return manifest.fields.find((f) => f.targetId === targetId && f.stars > 0)?.src;
}
